   *if it is rejected, set the process to 5, finally save the repair instance*/
  approve(
    sid: number,
    rid: number,
    reject: boolean,
    suggestion: string,
  ): ApprovalHistory {
    /*Definition Start*/
    let repair: Repair = l({
      logic: () =>
